import { IMAGES, type ImageName } from "@/lib/images.generated";

interface PictureProps {
  readonly name: ImageName;
  readonly alt: string;
  readonly sizes: string;
  /** The LCP image loads eagerly with high priority; everything else is lazy. */
  readonly priority?: boolean;
  readonly className?: string;
}

/**
 * Responsive <picture> over the AVIF and WebP files generated by `scripts/images.ts`.
 * The wrapper keeps the aspect ratio and a dominant-colour background, so lite mode or a failed
 * image never shifts the layout (EC-SITE-06).
 */
export function Picture({ name, alt, sizes, priority = false, className }: PictureProps) {
  const image = IMAGES[name];
  const srcSet = (sources: readonly { src: string; width: number }[]) =>
    sources.map((source) => `${source.src} ${source.width}w`).join(", ");
  const fallback = image.webp[1] ?? image.webp[0];
  return (
    <picture
      className={`block overflow-hidden ${className ?? ""}`}
      style={{ aspectRatio: `${image.width} / ${image.height}`, backgroundColor: image.color }}
    >
      <source type="image/avif" srcSet={srcSet(image.avif)} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet(image.webp)} sizes={sizes} />
      <img
        src={fallback?.src}
        alt={alt}
        width={image.width}
        height={image.height}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : "auto"}
        decoding={priority ? "sync" : "async"}
        data-decorative="true"
        className="block h-full w-full object-cover"
      />
    </picture>
  );
}
